var count=0;void Check(bool test,string label){if(!test)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}
async Task Reject(Func<Task> run,string label){try{await run();}catch(Exception e)when(e is SimRfqIntakeProblem or LibraryBomPermissionException){Check(true,label);return;}throw new Exception("Expected rejection: "+label);}
string Export(string assembly,string primary,string[] extras,string find="1",string qty="1",string unit="EA"){
 var rows=new List<string>{string.Join('\t',SimVproParser.Headers)+"\tDRAW#="+assembly+" REV A"};
 rows.Add(string.Join('\t',new[]{"001",primary,"Description","","1",qty,unit,"1","0","0","0","",""}));int i=2;
 foreach(var extra in extras)rows.Add(string.Join('\t',new[]{(i++).ToString("D3"),extra,"Description","","10",".0001",unit,"1","0","0","0","",""}));
 rows.Add(string.Join('\t',new[]{i.ToString("D3"),"","("+find+")R1","","1","0","","0","0","0","0","",""}));return string.Join('\n',rows)+"\n";
}
